using System;
using System.Collections.Generic;
using System.IO;
using System.Windows.Forms;
namespace Downfield {
public static partial class UiTests {
 static void LeagueScreens(GameForm f,string evidence){Set(f,"matchFixture",-1);Franchise club=Franchise.Create(new Profile(),new Roster());Set(f,"franchise",club);Set(f,"screen","roster");Set(f,"selection",0);f.SavePreview(Path.Combine(evidence,"roster.png"));System.Collections.IList hits=(System.Collections.IList)Get(f,"menuTargets");Check(hits.Count==26,"all 25 players and back button visible on one roster screen");Set(f,"navTime",0f);Tap(f,Keys.Down);Check((int)Get(f,"selection")==6,"roster down moves one visual row");Set(f,"navTime",0f);Tap(f,Keys.Right);Check((int)Get(f,"selection")==7,"roster right moves one card");Tap(f,Keys.Enter);Check((string)Get(f,"screen")=="player","card opens full player controls");Set(f,"screen","settings");Set(f,"selection",3);Set(f,"difficulty",2);Call(f,"ActivateSelection");Check((int)Get(f,"difficulty")==3&&GamePreferences.Load().Difficulty==3,"options selects and saves Extreme");f.SavePreview(Path.Combine(evidence,"options.png"));Call(f,"StartGame");Simulation s=(Simulation)Get(f,"game");Check(s.Difficulty==3,"franchise kickoff applies Extreme");Set(f,"screen","pause");Set(f,"selection",3);Call(f,"ActivateSelection");Check(s.Difficulty==0,"pause difficulty cycles Extreme to Rookie");Set(f,"matchFixture",-1);Set(f,"difficulty",1);
  while(!club.Complete){if(club.UserGame==null)club.Advance();else club.FinishGame(club.UserGame.Id,35,7);}club.NextSeason();Set(f,"screen","franchisehub");Set(f,"selection",0);Call(f,"ActivateSelection");Check((string)Get(f,"screen")=="draft","franchise play button opens pending draft");f.SavePreview(Path.Combine(evidence,"draft.png"));int count=club.DraftResults.Count;Set(f,"selection",0);Call(f,"ActivateSelection");Check((string)Get(f,"screen")=="confirm"&&((List<ClubPlayer>)Get(f,"confirmPlayers")).Count==1,"draft pick shows exact rookie portrait and contract");f.SavePreview(Path.Combine(evidence,"draft-confirm.png"));Set(f,"selection",1);Call(f,"ActivateSelection");Check(club.DraftResults.Count>count&&(string)Get(f,"screen")=="draft","confirmed pick advances CPU until next human pick");Set(f,"selection",club.Prospects.Count);Call(f,"ActivateSelection");Set(f,"selection",1);Call(f,"ActivateSelection");Check(!club.DraftActive&&club.DraftResults.Count==36,"auto draft menu completes all remaining league picks");f.SavePreview(Path.Combine(evidence,"draft-class.png"));Set(f,"screen","standings");Set(f,"selection",0);f.SavePreview(Path.Combine(evidence,"standings.png"));Check(((System.Collections.IList)Get(f,"menuTargets")).Count==13,"all twelve standings rows and roster scouting links visible");Set(f,"screen","club");f.SavePreview(Path.Combine(evidence,"office.png"));Set(f,"screen","home");
 }
